      errorMessage: '$error',
      timestamp: DateTime.now(),
    );
    await _processEvent(MessageStartEvent(failureMessage));
    await _processEvent(MessageEndEvent(failureMessage));
    await _processEvent(
      TurnEndEvent(message: failureMessage, toolResults: const []),
