      content: const [],
      api: model.api,
      provider: model.provider,
      model: model.id,
      usage: Usage.zero,
      stopReason: StopReason.aborted,
      errorMessage: lastFailure?.errorMessage ?? 'Request was aborted',
      timestamp: DateTime.now(),
