          ? null
          : () => externalSteeringProbe!(),
      maxEmptyRetries: maxEmptyRetries,
      emptyHiccupRetries: emptyHiccupRetries,
      emptyHiccupBaseDelay: emptyHiccupBaseDelay,
      emptyHiccupMaxBackoff: emptyHiccupMaxBackoff,
