      configSource: () async => _liveMemoryConfig(),
      onConfigChanged: () => unawaited(_refreshMemorySection()),
      // Semantic search + consolidate() need an LLM: memory → smol → main.
      llmProvider: HarnessLlmProvider(resolve: () => _resolveMemoryLlmSlot()),
