          homeDir: config.homeDir,
          os: config.osName,
          pathProbe: config.fsProbe,
          onWarning: (message) => io.writeln(tuiWarning(message)),
        ),
        snapshots: _snapshotStore,
        webSearch: config.webSearchConfig,
        sqlite: config.sqliteEngine,
        lsp: config.lspConfig,
        mcp: _mcp.manager,

