/// override's `omitMaxOutputTokens` lands on the model compat (AC7).
///
/// Throws [ConfigException] for unknown providers.
Model buildCatalogModel(
  String provider,
  String modelId, {
  String? baseUrl,
  int? contextWindow,
  int? maxTokens,
  List<String>? input,
  String? thinkingLevel,
  String? authHeader,
  Duration? connectTimeout,
