    id: modelId,
    name: modelId,
    api: spec.api,
    provider: spec.name,
    baseUrl: baseUrl ?? spec.defaultBaseUrl,
    reasoning: spec.reasoning,
    input: input ?? spec.input,
    thinkingLevel: caps.thinkingLevel,
    contextWindow: caps.contextWindow,
    maxTokens: caps.maxTokens,
    authHeader: authHeader,
