AssistantMessageEventStream _hangingStream(CancelToken? token) {
  final stream = AssistantMessageEventStream();
  unawaited(
    token?.onCancel.then((_) {
      stream.push(
        ErrorEvent(
          reason: StopReason.aborted,
          error: _assistant(
            stopReason: StopReason.aborted,
            errorMessage: 'aborted',
