/// The effective stream-idle patience for one model (gh-1617 I1):
/// the model's request-scoped window (gh-1554's top layer) over the
/// per-URL resolution (registry entries > global > default).
({Duration window, String source}) effectiveStreamIdleForModel(Model model) {
  final scoped = model.streamIdleTimeout;
  if (scoped != null) {
    return (
      window: scoped,
      source: model.timeoutScopeLabel ?? 'model override',  // hmm
