```dart
/// The effective run-idle window for the CURRENT model (gh-1617 I1):
/// [runIdleTimeout] (the floor) raised to cover the model's effective
/// stream-idle patience. Re-derived on every arm, so a mid-run roles
/// failover re-windows the watchdog around the model actually being
/// streamed (AC2), and a config re-seed applies from the next arm (E3:
/// no live re-arm of an armed timer).
Duration get _effectiveRunIdleWindow {
  final resolved = effectiveStreamIdleForModel(_state.model);
  return runIdleWatchdogWindow(floor: runIdleTimeout, effectiveIdle: resolved.window);
}
