          streamIdle: const Duration(seconds: 40),
        );
      expect(
        explicitStreamIdleForModel(_model('https://llama.test/v1'))!.$1,
        const Duration(seconds: 20),
      );
      expect(
        explicitStreamIdleForModel(_model('https://glm.test/v1'))!.$1,
