      'window', () {
    test('config: streamIdleTimeoutMs above the floor — the warmup '
        'completes, the run answers, no (zero-byte stall) abort', () async {
      final provider = _WarmingUpProvider(const Duration(milliseconds: 240));
      final agent = _agent(
