      final otherWarmup = _WarmingUpProvider(const Duration(milliseconds: 120));
      final uncovered = _agent(
        model: _model(baseUrl: 'https://other.test/v1'),
        provider: otherWarmup,
        floor: const Duration(milliseconds: 60),
