      );
      final errors = agent.state.messages
          .whereType<AssistantMessage>()
          .where((m) => m.errorMessage?.contains('(zero-byte stall)') ?? false);
      expect(errors, isEmpty, reason: 'no zero-byte abort under config');
    });
  });

